import java.sql.*;import java.util.*;import java.nio.file.*;import com.alibaba.fastjson2.*;
/** Ordinary set-frontier JDBC reference; preserves original SNB output contracts. */
public class SnbSetSql {
 public interface RegionBoundary{void enter(Connection c)throws Exception;void leave(Connection c)throws Exception;}static RegionBoundary regionBoundary;static boolean schemaReady=false;static Set<String>knownTypes=new HashSet<>();static Map<String,String>clientRootContext=new HashMap<>();static Map<String,Long>kinds=new LinkedHashMap<>();static String url;public static void configure(Path p){query=System.getProperty("snb.query");url=System.getProperty("snb.url","jdbc:mysql://127.0.0.1:"+System.getProperty("experiment.mysql.port","55337")+"/jac_snb_six_20261020?useSSL=false&useUnicode=true&characterEncoding=UTF-8");}
 static int planNo=0;static long calls;static List<String> commands=new ArrayList<>();static String query=System.getProperty("snb.query");
 static String j(String a,String k){return "JSON_UNQUOTE(JSON_EXTRACT("+a+".props,'$.archetype."+k+"'))";}
 static String num(String a,String k){return "CAST("+j(a,k)+" AS SIGNED)";}
 static String marks(int n){return String.join(",",Collections.nCopies(n,"?"));}
 static String uuid(String s){if(s.indexOf('-')>=0)return s;s=String.format("%32s",s.replace("-","")).replace(' ','0');return s.substring(0,8)+"-"+s.substring(8,12)+"-"+s.substring(12,16)+"-"+s.substring(16,20)+"-"+s.substring(20);}
 static List<List<Object>> sql(Connection c,String q,Object...args)throws Exception{calls++;commands.add(q);List<List<Object>>out=new ArrayList<>();try(PreparedStatement s=c.prepareStatement(q)){for(int i=0;i<args.length;i++){Object x=args[i];if(x instanceof Long)s.setLong(i+1,(Long)x);else if(x instanceof Integer)s.setInt(i+1,(Integer)x);else s.setString(i+1,(String)x);}try(PreparedStatement ex=c.prepareStatement("EXPLAIN FORMAT=JSON "+q)){for(int i=0;i<args.length;i++){Object x=args[i];if(x instanceof Long)ex.setLong(i+1,(Long)x);else if(x instanceof Integer)ex.setInt(i+1,(Integer)x);else ex.setString(i+1,(String)x);}try(ResultSet er=ex.executeQuery()){er.next();JSONObject detail=new JSONObject();detail.put("sql",q);detail.put("parameters",Arrays.asList(args));detail.put("plan",JSON.parse(er.getString(1)));Files.write(Paths.get(System.getProperty("snb.planDir"),"plan-"+(planNo++)+".json"),detail.toJSONString().getBytes("UTF-8"));}}try(ResultSet r=s.executeQuery()){while(r.next()){List<Object>row=new ArrayList<>();for(int i=1;i<=r.getMetaData().getColumnCount();i++)row.add(r.getString(i));out.add(row);}}}return out;}
 static void command(Connection c,String s)throws Exception{calls++;commands.add(s);try(Statement st=c.createStatement()){st.execute(s);}}
 static JSONObject props(Connection c,String id)throws Exception{return JSON.parseObject((String)sql(c,"SELECT props FROM anchors WHERE id=?",id).get(0).get(0)).getJSONObject("archetype");}
 static Set<String> neighbors(Connection c,Collection<String> f)throws Exception{Set<String>n=new LinkedHashSet<>();if(f.isEmpty())return n;List<Object>a=new ArrayList<>();a.addAll(f);a.addAll(f);String m=marks(f.size());for(List<Object>r:sql(c,"SELECT e.dst FROM anchors e JOIN anchors n ON n.id=e.dst AND n.kind='NodeAnchor' AND n.arch_type='Person' WHERE e.kind='EdgeAnchor' AND e.arch_type='Knows' AND e.src IN("+m+") UNION SELECT e.src FROM anchors e JOIN anchors n ON n.id=e.src AND n.kind='NodeAnchor' AND n.arch_type='Person' WHERE e.kind='EdgeAnchor' AND e.arch_type='Knows' AND e.dst IN("+m+")",a.toArray()))n.add((String)r.get(0));return n;}
 static JSONObject personFields(JSONObject p){JSONObject r=new JSONObject();for(String k:new String[]{"firstName","lastName","birthday","locationIP","browserUsed","gender","creationDate"})r.put(k,p.get(k));return r;}
 public static JSONObject request(Connection c,JSONObject in)throws Exception{calls=0;commands.clear();command(c,"START TRANSACTION READ ONLY");command(c,"SET SESSION innodb_lock_wait_timeout=10");try{if(regionBoundary!=null)regionBoundary.enter(c);JSONObject out=body(c,in);if(regionBoundary!=null)regionBoundary.leave(c);command(c,"COMMIT");return out;}catch(Exception e){command(c,"ROLLBACK");throw e;}}
 public static JSONObject body(Connection c,JSONObject in)throws Exception{
 JSONObject out=new JSONObject();String pid=in.containsKey("person_jid")?uuid(in.getString("person_jid")):null;
 if(query.equals("is1")){List<List<Object>>r=sql(c,"SELECT p.props,"+num("n","place_id")+" FROM anchors p LEFT JOIN anchors e ON e.src=p.id AND e.kind='EdgeAnchor' AND e.arch_type='IsLocatedIn' LEFT JOIN anchors n ON n.id=e.dst AND n.kind='NodeAnchor' AND n.arch_type='Place' WHERE p.id=? ORDER BY e.seq,e.id LIMIT 1",pid);out=personFields(JSON.parseObject((String)r.get(0).get(0)).getJSONObject("archetype"));out.put("cityId",r.get(0).get(1)==null?-1:Long.valueOf((String)r.get(0).get(1)));return out;}
 if(query.equals("is3")){List<JSONObject>outrows=new ArrayList<>();String projection=num("p","person_id")+","+j("p","firstName")+","+j("p","lastName");String q="SELECT "+projection+" FROM (SELECT e.dst id FROM anchors e WHERE e.src=? AND e.kind='EdgeAnchor' AND e.arch_type='Knows' UNION ALL SELECT e.src id FROM anchors e WHERE e.dst=? AND e.kind='EdgeAnchor' AND e.arch_type='Knows') f JOIN anchors p ON p.id=f.id AND p.kind='NodeAnchor' AND p.arch_type='Person' ORDER BY "+num("p","person_id");for(List<Object>r:sql(c,q,pid,pid)){JSONObject o=new JSONObject();o.put("personId",Long.valueOf((String)r.get(0)));o.put("firstName",r.get(1));o.put("lastName",r.get(2));outrows.add(o);}out.put("friends",outrows);out.put("count",outrows.size());return out;}
 if(query.equals("ic13")||query.equals("ic1")){String start=query.equals("ic13")?uuid(in.getString("person1_jid")):pid;String target=query.equals("ic13")?uuid(in.getString("person2_jid")):null;Map<String,Integer>dist=new LinkedHashMap<>();dist.put(start,0);Set<String>front=new LinkedHashSet<>(Arrays.asList(start));int answer=start.equals(target)?0:-1;
 for(int d=1;d<=(query.equals("ic1")?3:6)&&answer<0;d++){Set<String>n=neighbors(c,front);n.removeAll(dist.keySet());for(String x:n)dist.put(x,d);if(target!=null&&n.contains(target)){answer=d;break;}if(n.isEmpty())break;front=n;}
 if(query.equals("ic13")){out.put("length",answer);return out;}dist.remove(start);List<JSONObject>found=new ArrayList<>();if(!dist.isEmpty()){List<Object>a=new ArrayList<>(dist.keySet());a.add(in.getString("first_name"));for(List<Object>r:sql(c,"SELECT p.id,"+num("p","person_id")+","+j("p","lastName")+" FROM anchors p WHERE p.id IN("+marks(dist.size())+") AND "+j("p","firstName")+"=?",a.toArray())){JSONObject x=new JSONObject();x.put("personId",Long.valueOf((String)r.get(1)));x.put("lastName",r.get(2));x.put("distance",dist.get(r.get(0)));found.add(x);}}found.sort((a,b)->{int t=Integer.compare(a.getIntValue("distance"),b.getIntValue("distance"));if(t==0)t=a.getString("lastName").compareTo(b.getString("lastName"));if(t==0)t=Long.compare(a.getLongValue("personId"),b.getLongValue("personId"));return t;});out.put("people",found.subList(0,Math.min(20,found.size())));return out;}
 return messages(c,in,pid);
 }
 static JSONObject messages(Connection c,JSONObject in,String pid)throws Exception{
 boolean recent=query.equals("is2");Set<String>authors=recent?new LinkedHashSet<>(Arrays.asList(pid)):neighbors(c,Arrays.asList(pid));List<JSONObject>outrows=new ArrayList<>();JSONObject out=new JSONObject();if(authors.isEmpty()){out.put("messages",outrows);return out;}
 List<Object>args=new ArrayList<>(authors);String date=recent?"":" AND "+num("m","creationDate")+"<=?";if(!recent)args.add(in.getLong("max_date"));String mid="CASE WHEN m.arch_type='Post' THEN "+num("m","post_id")+" ELSE "+num("m","comment_id")+" END";
 List<List<Object>>rows=sql(c,"SELECT DISTINCT m.id,m.arch_type,m.props,a.id,a.props,"+num("m","creationDate")+" AS creation_sort,"+mid+" AS id_sort FROM anchors hc JOIN anchors m ON m.id=hc.src AND m.kind='NodeAnchor' AND m.arch_type IN('Post','Comment') JOIN anchors a ON a.id=hc.dst AND a.kind='NodeAnchor' AND a.arch_type='Person' WHERE hc.kind='EdgeAnchor' AND hc.arch_type='HasCreator' AND hc.dst IN("+marks(authors.size())+")"+date+" ORDER BY creation_sort DESC,id_sort"+(recent?" DESC":" ASC")+" LIMIT "+(recent?10:20),args.toArray());
 Map<String,String>root=new LinkedHashMap<>();Map<String,JSONObject>node=new HashMap<>();Map<String,String>current=new LinkedHashMap<>();
 for(List<Object>r:rows){String id=(String)r.get(0);JSONObject p=JSON.parseObject((String)r.get(2)).getJSONObject("archetype");node.put(id,p);if(r.get(1).equals("Post"))root.put(id,id);else current.put(id,id);}
 if(recent){Set<String>seen=new HashSet<>();for(int depth=0;!current.isEmpty();depth++){if(depth>1000)throw new IllegalStateException("ReplyOf cycle/depth");Set<String>front=new LinkedHashSet<>(current.values());Map<String,String>next=new LinkedHashMap<>();for(List<Object>r:sql(c,"SELECT e.src,e.dst,n.arch_type,n.props FROM anchors e JOIN anchors n ON n.id=e.dst AND n.kind='NodeAnchor' WHERE e.kind='EdgeAnchor' AND e.arch_type='ReplyOf' AND e.src IN("+marks(front.size())+") ORDER BY e.seq,e.id",front.toArray())){String src=(String)r.get(0),dst=(String)r.get(1);node.put(dst,JSON.parseObject((String)r.get(3)).getJSONObject("archetype"));for(Map.Entry<String,String>e:current.entrySet())if(e.getValue().equals(src)&&!next.containsKey(e.getKey())&&!root.containsKey(e.getKey())){if(r.get(2).equals("Post"))root.put(e.getKey(),dst);else next.put(e.getKey(),dst);}}current=next;}
 }
 Map<String,JSONObject>rootAuthors=new LinkedHashMap<>();Set<String>posts=new LinkedHashSet<>(root.values());if(recent&&!posts.isEmpty())for(List<Object>r:sql(c,"SELECT e.src,p.props FROM anchors e JOIN anchors p ON p.id=e.dst AND p.kind='NodeAnchor' AND p.arch_type='Person' WHERE e.kind='EdgeAnchor' AND e.arch_type='HasCreator' AND e.src IN("+marks(posts.size())+") ORDER BY e.seq,e.id",posts.toArray()))rootAuthors.put((String)r.get(0),JSON.parseObject((String)r.get(1)).getJSONObject("archetype"));
 for(List<Object>r:rows){String id=(String)r.get(0);boolean post=r.get(1).equals("Post");JSONObject p=node.get(id),a=JSON.parseObject((String)r.get(4)).getJSONObject("archetype");JSONObject x=new JSONObject();x.put("id",p.get(post?"post_id":"comment_id"));x.put("creationDate",p.get("creationDate"));String content=p.getString("content");x.put("content",post&&(content==null||content.isEmpty())?p.get("imageFile"):content);
 if(recent){x.put("kind",post?"post":"comment");String rootid=root.get(id);if(post){x.put("origPostId",p.get("post_id"));x.put("origAuthorId",a.get("person_id"));}else if(rootid!=null){x.put("origPostId",node.get(rootid).get("post_id"));if(rootAuthors.containsKey(rootid))x.put("origAuthorId",rootAuthors.get(rootid).get("person_id"));}}
 else{x.put("authorId",a.get("person_id"));x.put("authorFirst",a.get("firstName"));x.put("authorLast",a.get("lastName"));}outrows.add(x);}
 out.put("messages",outrows);return out;
 }
 public static void main(String[]a)throws Exception{query=a[0];Path catalog=Paths.get(a[1]),out=Paths.get(a[2]);Files.createDirectory(out);JSONArray inputs=JSON.parseObject(new String(Files.readAllBytes(catalog),"UTF-8")).getJSONArray(query);try(Connection c=DriverManager.getConnection(System.getProperty("snb.url","jdbc:mysql://127.0.0.1:55337/jac_snb_six_20261020?useSSL=false&useUnicode=true&characterEncoding=UTF-8"),"root","")){for(Object value:inputs.subList(0,1)){JSONObject input=(JSONObject)value;long start=System.nanoTime();JSONObject result=request(c,input.getJSONObject("body"));JSONObject row=new JSONObject();row.put("idx",input.get("idx"));row.put("query",query);row.put("result",result);row.put("expected_canonical_sha256",input.get("expected_canonical_sha256"));row.put("ms",(System.nanoTime()-start)/1e6);row.put("source_calls",calls);row.put("sql",new ArrayList<>(commands));Files.write(out.resolve("rows.jsonl"),(row.toJSONString()+"\n").getBytes("UTF-8"),StandardOpenOption.CREATE,StandardOpenOption.APPEND);}}}
}
